                      db=None, imp_user=None, dehydration_hooks=None,
                      hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    output = []
    if mode is not None:
        if mode.upper() not in ["READ", "WRITE"]:
            raise ValueError("Invalid `mode` value `{}`".format(mode))
        output.append(("\x0D\x00", (Neo4jType.STRING, mode.upper())))
    if bookmarks is not None:
        if not isinstance(bookmarks, Iterable):
            raise ValueError("Invalid `bookmarks` value `{}`".format(bookmarks))
        output.append(("\x0D\x19", (Neo4jType.STRING, neo4j.typeconvert.to_byte(bookmarks))))
    if metadata is not None:
        if not isinstance(metadata, Mapping):
            raise ValueError("Invalid `metadata` value `{}`".format(metadata))
        output.append(("\x0D\x1A", (Neo4jType.STRING, neo4j.typeconvert.to_byte(metadata))))
    if timeout is not None:
        if not isinstance(timeout, (Numeric, Integral)):
            raise ValueError("Invalid `timeout` value `{}`".format(timeout))
        output.append(("\x0D\x1B", (Neo4jType.STRING, neo4j.typeconvert.to_byte(timeout))))
    if db is not None:
        if not isinstance(db, (Numeric, Integral)):
            raise ValueError("Invalid `db` value `{}`".format(db))
        output.append(("\x0D\x18", (Neo4jType.STRING, neo4j.typeconvert.to_byte(db))))
    if imp_user is not None:
        if not isinstance(imp_user, (Numeric, Integral)):
            raise ValueError("Invalid `imp_user` value `{}`".format(imp_user))
        output.append(("\x0D\x1D", (Neo4jType.STRING, neo4j.typeconvert.to_byte(imp_user))))
    if dehydration_hooks is not None:
        if not isinstance(dehydration_hooks, Mapping):
            raise ValueError(
                "Invalid `dehydration_hooks` value `{}`".format(dehydration_hooks))
        output.append(("\x0D\x15", (Neo4jType.STRING, neo4j.typeconvert.to_byte(dehydration_hooks))))
    if hydration_hooks is not None:
        if not isinstance(hydration_hooks, Mapping):
            raise ValueError(
                "Invalid `hydration_hooks` value `{}`".format(hydration_hooks))
        output.append(("\x0D\x16", (Neo4jType.STRING, neo4j.typeconvert.to_byte(hydration_hooks))))
    for key, value in handlers.items():
        if not callable(value):
            raise ValueError("Invalid `handler` value `{}`".format(value))
        output.append(("\x0D\x17", (Neo4jType.STRING, neo4j.typeconvert.to_byte(value))))
    return Response(self._connection, output=output)

