def shuffled(seq: Sequence[str], seed: int = None) -> list[str]:
    """
    Deterministically shuffle `seq` using `seed` as the random seed.

    If `seed` is not provided, the result is non-deterministic.
    """
    if seed is not None:
        random.seed(seed)
    return list(random.sample(seq, len(seq)))

