def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if platform.system() == "Windows":
        return tuple(cmd)
    else:
        cmd_list = list(cmd)
        if len(cmd_list) > 0 and cmd_list[0].startswith("#!"):
            # Replace shebang with #!python on windows
            cmd_list[0] = "#!python" + cmd_list[0][2:]
        return tuple(cmd_list)

