def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.

    Args:
        e (Exception): Any exception instance.
        max_level (int): Maximum call stack level (default 30)
        max_path_level (int): Maximum path level (default 5)

    Returns:
        str: The exception readable string
    """
    if not isinstance(e, Exception):
        raise TypeError("'e' must be an instance of 'Exception'")
    if not isinstance(max_level, int):
        raise TypeError("'max_level' must be an instance of 'int'")
    if not isinstance(max_path_level, int):
        raise TypeError("'max_path_level' must be an instance of 'int'")
    if max_level < 1:
        raise ValueError("'max_level' must be greater than 0")
    if max_path_level < 1:
        raise ValueError("'max_path_level' must be greater than 0")

    # Get the traceback
    tb = sys.exc_info()[2]
    tbinfo = traceback.extract_tb(tb)
    if not tbinfo:
        return str(e)

    # Build the message
    msg = f"{type(e).__name__}: {e}"
    for level, (filename, line, funcname, text) in enumerate(tbinfo):
        if level >= max_level:
            break
        msg += "\n"
        msg += f"  File {filename}, line {line}"
        if funcname:
            msg += f", in {funcname}"
        if text:
            msg += "\n    " + text.strip()

    # Return the exception readable string
    return msg

