    the in-style parameters.

    :param sql: The SQL query.
    :type sql: str or bytes

    :param params: The set of in-style parameters. It maps each parameter to a value.
    :type params: Mapping or Sequence

    :return: A tuple containing the formatted SQL query and the set of converted out-style parameters.
    :rtype: tuple[str or bytes, dict or list]
    """
    if self.in_style == ParameterStyle.NAMED:
        if not isinstance(params, Mapping):
            raise ValueError("parameters should be a mapping when in_style is named")
    elif self.in_style == ParameterStyle.ORDINAL:
        if not isinstance(params, Sequence):
            raise ValueError("parameters should be a sequence when in_style is ordinal")
    else:
        raise ValueError("in_style should be one of named or ordinal")

    if self.out_style == ParameterStyle.NAMED:
        out_params = {}
    elif self.out_style == ParameterStyle.ORDINAL:
        out_params = []
    else:
        raise ValueError("out_style should be one of named or ordinal")

    if self.in_style == ParameterStyle.NAMED:
        key_pattern = r" (?P<key>\w+)\b"
    else:
        key_pattern = r" ?(?P<key>\w+)"

    key_regex = re.compile(key_pattern)

    for match in key_regex.finditer(sql):
        key = match.group("key")
        if key.lower() in params:
