    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or :class:`list`).
    """
    if self.param_style in (NamedParam, InputParam):
        if not isinstance(params, Mapping):
            raise ValueError("Params should be a mapping for in-style params")
    elif self.param_style in (OrdinalParam, PyFormatParam):
        if not isinstance(params, Sequence):
            raise ValueError("Params should be a sequence for in-style params")

    if self.param_style == NamedParam:
        for i, (param, value) in enumerate(params.items()):
            if type(param) is not str:
                raise ValueError(f"Param name should be a string, got: {param!r}")
            if not param.isidentifier():
                raise ValueError(f"Param name {param!r} is not valid")
            sql = sql.replace(f"${i}", param, 1)

            if isinstance(value, (str, bytes)):
                value = value.replace("$", "\\$")
            params[param] = value

            del params[i]
    elif self.param_style == InputParam:
        for i, value in enumerate(params):
            sql = sql.replace(f":{i+1}", str(value), 1)

    elif self.param_style == OrdinalParam:
        placeholder_regex = re.compile(r"(\?|%s)")
        pos = 0
        for m in placeholder_regex.finditer(sql):
            sql = sql[:m.start(0)] + str(params[pos]) + sql[m.end(0):]
            pos += 1

    elif self.param_style == PyFormatParam:
        params = list(params)
        sql = sql.replace(f"{self.param_marker}", "({})")
        return sql % params

