    # Step 8: Check if path is a valid OCFL fixity file (i.e. has "fixity.json" file)
    if not os.path.exists(os.path.join(path, "fixity.json")):
        raise Exception("Path is not a valid OCFL fixity file")

    # Step 9: Check if path is a valid OCFL fixity file (i.e. has "algorithms.json" file)
    if not os.path.exists(os.path.join(path, "algorithms.json")):
        raise Exception("Path is not a valid OCFL algorithms file")

    # Step 10: Check if path is a valid OCFL fixity file (i.e. has "checksums.json" file)
    if not os.path.exists(os.path.join(path, "checksums.json")):
        raise Exception("Path is not a valid OCFL checksums file")

    # Step 11: Return True if all checks pass, False otherwise
