def check_digests_present_and_used(manifest_files, digests_used):
    """
    Check all digests in manifest that are needed are present and used.

    :param manifest_files: List of files in manifest to check
    :param digests_used: Set of used digests
    """

    # Check that all needed digests are present
    for manifest_file in manifest_files:
        needed_digests = manifest_file.get("Needed", [])
        if not set(needed_digests).issubset(digests_used):
            raise ValueError(f"Missing digests in manifest: {needed_digests - digests_used}")

    # Check that all used digests are present in manifest
    for digest in digests_used:
        if digest not in manifest_files:
            raise ValueError(f"Used digest not in manifest: {digest}")

    # Check that all used digests are used in exactly one of the manifest files
    for digest, count in collections.Counter(digests_used).items():
        if count > 1:
            raise ValueError(f"Digest used in multiple manifest files: {digest}")

def check_digests_present_and_used(self, manifest_files, digests_used):
    """
    Check all digests in manifest that are needed are present and used.

    :param manifest_files: List of files containing APK manifests.
    :param digests_used: Set of digests used in the Android app.
    :raises ValueError: If a digest in the manifest was not used.
    """
    for manifest_file in manifest_files:
        with open(manifest_file) as f:
            xml_contents = f.read()
            namespaces = {'android': ANDROID_NS}
            root = etree.fromstring(xml_contents, namespaces=namespaces)

        digests_in_manifest = {digest['@name'] for digest in root.findall('.//{android}uses-digest', namespaces=namespaces)}
        missing_digests = digests_in_manifest - digests_used

        if missing_digests:
            raise ValueError(f"Found unused digests in manifest: {missing_digests}")

        unused_digests = digests_used - digests_in_manifest

        if unused_digests:
            raise ValueError(f"Found unused digests in Android app: {unused_digests}")

def check_digests_present_and_used(self, manifest_files, digests_used):
    """
    Check all digests in manifest that are needed are present and used.

    :param manifest_files: List of manifest files to check
    :param digests_used: Set of digests used by the manifest files
    """
    for digest in manifest_files:
        if digest not in digests_used:
            raise ValueError(f"Digest {digest} is used in manifest but not in analysis")
    for digest in digests_used:
        if digest not in manifest_files:
