def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("Expected an instance of InventoryValidator as input, but received {0!r}.".format(prior))

    if prior.inventory is None:
        raise ValueError("The input inventory object is None.")

    if self.inventory is None:
        raise ValueError("The current inventory object is None.")

    if prior.inventory.name != self.inventory.name:
        raise ValueError("The name of the current inventory object is '{0}', but the input"
                         " inventory object has name '{1}'.".format(self.inventory.name,
                                                                     prior.inventory.name))

    if set(prior.inventory.parameters.keys()) != set(self.inventory.parameters.keys()):
        raise ValueError("The current inventory object has parameters {0!r}, but the input"
                         " inventory object has parameters {1!r}.".format(self.inventory.parameters.keys(),
                                                                          prior.inventory.parameters.keys()))

    for param in self.inventory.parameters:
        if param in prior.inventory.parameters:
            if prior.inventory.parameters[param] != self.inventory.parameters[param]:
                raise ValueError("The value of parameter {0} is {1}, but the input"
                                 " inventory object has value {2}.".format(param,
                                                                           self.inventory.parameters[param],
                                                                           prior.inventory.parameters[param]))

    if set(prior.inventory.species.keys()) != set(self.inventory.species.keys()):
        raise ValueError("The current inventory object has species {0!r}, but the input"
                         " inventory object has species {1!r}.".format(self.inventory.species.keys(),
                                                                       prior.inventory.species.keys()))

    for specie in self.inventory.species:
        if specie in prior.inventory.species:
            if prior.inventory.species[specie] != self.inventory.species[specie]:
                raise ValueError("The amount of species {0} is {1}, but the input"
                                 " inventory object has amount {2}.".format(specie,
                                                                            self.inventory.species[specie],
                                                                            prior.inventory.species[specie]))

