def get_version_file_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    :param inventory: Inventory of all versions in state
    :type inventory: dict
    :param version: Version in inventory to get file map for
    :type version: str
    :return: Dictionary of logical path -> set of files
    :rtype: dict
    """

    version_files = inventory[version]
    logical_path_map = {}

    for version_file in version_files:
        filename = version_file.split("/")[-1]
        logical_path = filename.split("__")[0]
        if logical_path in logical_path_map:
            logical_path_map[logical_path].add(filename)
        else:
            logical_path_map[logical_path] = {filename}

    return logical_path_map

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """

    version_details = get_version_details(version)
    inventory_details = parse_inventory(inventory)
    logical_path_map = {}

    for content_file in version_details["content_files"]:
        if content_file in inventory_details["all_files"]:
            path_in_state = content_file["logical_path_in_state"]
            if path_in_state in logical_path_map:
                logical_path_map[path_in_state].add(content_file["path_on_disk"])
            else:
                logical_path_map[path_in_state] = {content_file["path_on_disk"]}

    return logical_path_map

