            raise ValueError(f"Invalid fixity hash for file {file}: {hash_list}")

        if any(not hash[len("sha256:"):].isalnum() for hash in hash_list):
            raise ValueError(f"Invalid fixity hash for file {file}: {hash_list}")

    # Check that the number of fixity hashes for each file is consistent with the manifest
    for file, hash_list in fixity["files"].items():
        if len(hash_list) != math.floor(math.log2(metadata["size"][file] / 255)) + 1:
            raise ValueError(f"Inconsistent number of fixity hashes for file {file}: {hash_list}")

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("fixity must be a dict")
    if not isinstance(manifest_files, list):
        raise ValueError("manifest_files must be a list")

    for file_hash in fixity:
        if not isinstance(file_hash, dict):
            raise ValueError("file_hash must be a dict")
        if not all(key in file_hash for key in ("filename", "size", "hash")):
            raise ValueError("file_hash must contain keys 'filename', 'size', and 'hash'")
        if file_hash["filename"] not in manifest_files:
            raise ValueError("file_hash contains a filename not in the manifest")

    for file_info in manifest_files:
        if not isinstance(file_info, dict):
            raise ValueError("file_info must be a dict")
        if not all(key in file_info for key in ("filename", "size")):
            raise ValueError("file_info must contain keys 'filename' and 'size'")
        if file_info["filename"] not in fixity:
            raise ValueError("manifest file not present in fixity hashes")

    # If we got this far, the fixity block is valid.
    return True

