      number = issue[0]

  # Check for a double digit number
  if number is None:
    if len(issue) > 1 and issue[0:2].isdigit():
      number = issue[0:2]

  # Check for a triple digit number
  if number is None:
    if len(issue) > 2:
      number = issue[0:3]

  # Return the tuple
  return (number, supplement)

