def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for arg in args:
        if isinstance(arg, (And, Or)):
            op = arg.op
            lhs, rhs = arg.lhs, arg.rhs
            if isinstance(rhs, (And, Or)):
                op1, op2 = op, rhs.op
                lhs1, rhs1 = lhs, rhs.lhs
                rhs2 = rhs.rhs
                if op1 == op2:
                    result.append(op(lhs1, op(lhs2, rhs2)))
                elif op1.invert() == op2:
                    result.append(op1(lhs1, op1(lhs2, rhs2)))
                else:
                    result.append(op(op2(lhs1, rhs1), op1(lhs2, rhs2)))
            elif isinstance(rhs, Not):
                op1, op2 = op, rhs.op
                lhs1, rhs1 = lhs, rhs.lhs
                if op1 == op2:
                    result.append(op(lhs1, op2(rhs1, lhs1)))
                elif op1.invert() == op2:
                    result.append(op1(lhs1, op2(rhs1, lhs1)))
                else:
                    result.append(op(lhs1, op1(rhs1, lhs1)))
            else:
                result.append(arg)
        elif isinstance(arg, Not):
            op = arg.op
            lhs = arg.lhs
            if isinstance(lhs, (And, Or)):
                op1, op2 = lhs.op, op
                lhs1, lhs2 = lhs.lhs, lhs.rhs
                if op1 == op2:
                    result.append(op(op1(lhs1, lhs2), lhs2))
                elif op1.invert() == op2:
                    result.append(op2(op1(lhs1, lhs2), lhs2))
                else:
                    result.append(op(lhs1, op1(lhs2, lhs1)))
            elif isinstance(lhs, Not):
                op1, op2 = lhs.op, op
                lhs1, lhs2 = lhs.lhs, lhs.rhs
                if op1 == op2:
                    result.append(op(op2(lhs1, lhs2), lhs2))
                elif op1.invert() == op2:
                    result.append(op1(op2(lhs1, lhs2), lhs2))
                else:
                    result.append(op(lhs1, op1(lhs2, lhs1)))
            else:
                result.append(Not(op(lhs, lhs)))
        else:
            result.append(arg)
    return result

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if arg.is_and():
            left, right = arg.args
            if left.is_or():
                left_left, left_right = left.args
                if left_left == self:
                    new_args.append(left_left)
                    continue
                elif left_right == self:
                    new_args.append(left_right)
                    continue
            elif right.is_or():
                right_left, right_right = right.args
                if right_left == self:
                    new_args.append(right_left)
                    continue
                elif right_right == self:
                    new_args.append(right_right)
                    continue
        elif arg.is_or():
            left, right = arg.args
            if left == self:
                new_args.append(left)
                continue
            elif right == self:
                new_args.append(right)
                continue
        new_args.append(arg)
    return new_args

