def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if arg.is_and():
            left, right = arg.args
            if left.is_or():
                left_left, left_right = left.args
                if left_left == self:
                    new_args.append(left_left)
                    continue
                elif left_right == self:
                    new_args.append(left_right)
                    continue
            elif right.is_or():
                right_left, right_right = right.args
                if right_left == self:
                    new_args.append(right_left)
                    continue
                elif right_right == self:
                    new_args.append(right_right)
                    continue
        elif arg.is_or():
            left, right = arg.args
            if left == self:
                new_args.append(left)
                continue
            elif right == self:
                new_args.append(right)
                continue
        new_args.append(arg)
    return new_args

