def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Initialize the inventory data structure
    inventory = {}

    # Iterate over the version directories
    for version in version_dirs:
        # Get the inventory file path for this version
        inventory_file_path = os.path.join(self.root, 'inventories', f'{version}.json')

        # Load the inventory file
        with open(inventory_file_path, 'r') as inventory_file:
            inventory[version] = json.load(inventory_file)

        # Check if the inventory data structure is not None
        if inventory[version] is None:
            raise ValueError(f'Inventory for version {version} is not found')

        # Check if the inventory contains the correct file types
        for file_type in ['jpg', 'xlsx', 'pdf', 'txt']:
            if file_type not in inventory[version]['file_types']:
                raise ValueError(f'Inventory for version {version} does not contain file type {file_type}')

        # Check if the inventory contains the correct content digests
        for file_type in inventory[version]['file_types']:
            for file_name in inventory[version]['file_types'][file_type]:
                file_path = os.path.join(self.root, 'files', file_type, file_name)
                expected_digest = inventory[version]['file_types'][file_type][file_name]['digest']
                actual_digest = calculate_digest(file_path)
                if actual_digest != expected_digest:
                    raise ValueError(f'Inventory for version {version} contains incorrect content digest for file {file_type}/{file_name}')

        # Update the root inventory with the content digests from this version
        for file_type in inventory[version]['file_types']:
            for file_name in inventory[version]['file_types'][file_type]:
                digest = inventory[version]['file_types'][file_type][file_name]['digest']
                if file_type not in self.root_inventory['file_types']:
                    self.root_inventory['file_types'][file_type] = {}
                self.root_inventory['file_types'][file_type][file_name] = digest

        # Commit the changes to the root inventory
        with open(os.path.join(self.root, 'inventories', 'root.json'), 'w') as inventory_file:
            json.dump(self.root_inventory, inventory_file)

