def deep_merge_nodes(nodes):
    merged_nodes = []
    for node in nodes:
        key, value = node
        if not value:
            continue
        # If the key is not already present in the dictionary, just add it
        if key not in merged_nodes:
            merged_nodes[key] = value
        else:
            # If the key is already present in the dictionary, deep merge the values
            existing_value = merged_nodes[key]
            if isinstance(existing_value, dict):
                merged_nodes[key] = {**existing_value, **value}
            elif isinstance(existing_value, list):
                merged_nodes[key] = existing_value + value
            else:
                # If the value is not a dictionary or list, just use the last value
                # for the key
                merged_nodes[key] = value
    return merged_nodes

