def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not size:
        return 0

    unit = size[-2:]
    value = int(size[:-2])

    if unit == 'KB':
        return value * 1024
    elif unit == 'MB':
        return value * 1024 ** 2
    elif unit == 'GB':
        return value * 1024 ** 3
    elif unit == 'TB':
        return value * 1024 ** 4
    elif unit == 'PB':
        return value * 1024 ** 5
    elif unit == 'EB':
        return value * 1024 ** 6
    elif unit == 'ZB':
        return value * 1024 ** 7
    elif unit == 'YB':
        return value * 1024 ** 8
    else:
        raise ValueError(f"Invalid unit: {unit}")

