def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("number must be non-negative")
    if not alphabet or not all(character in alphabet and len(character) == 1 for character in alphabet):
        raise ValueError("alphabet must be a non-empty list of unique characters")
    if padding is not None and padding < 0:
        raise ValueError("padding must be None or non-negative")

    # Create a dictionary mapping integers to characters
    int_to_char = {i: character for i, character in enumerate(alphabet)}

    # Create a list of characters corresponding to the number's digits
    characters = []
    while number > 0:
        characters.append(int_to_char[number % len(alphabet)])
        number //= len(alphabet)

    # Pad the output with the alphabet's zero character if necessary
    if padding is not None and number != 0:
        zeros = padding - len(characters)
        characters = [int_to_char[0]] * zeros + characters

    return "".join(characters[::-1])

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    # Convert the integer to a list of digits in the given base
    digits = []
    while number > 0:
        digits.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    # Pad the list with leading zeros if necessary
    if padding is not None and len(digits) < padding:
        digits.extend([alphabet[0]] * (padding - len(digits)))

    # Reverse the list and join it back into a string
    return "".join(reversed(digits))

