def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    # Check for invalid inputs
    if not isinstance(hist, Hist):
        raise ValueError("hist must be a Hist object")
    if not callable(make_value):
        raise ValueError("make_value must be a callable")
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")
    if not isinstance(field_names, (list, tuple)):
        raise ValueError("field_names must be a list or tuple")
    if scale is not None and not isinstance(scale, Scale):
        raise ValueError("scale must be a Scale object or None")

    # Initialize the graph
    graph = Graph()

    # Set the scale
    if scale is None:
        graph.scale = hist.scale
    else:
        graph.scale = scale

    # Get the data
    data = hist.data

    # Set the field names
    graph.field_names = field_names

    # Loop through the bins
    for i, bin in enumerate(data):
        # Get the coordinate
        if get_coordinate == "left":
            coordinate = bin.left
        elif get_coordinate == "right":
            coordinate = bin.right
        else:
            coordinate = (bin.left + bin.right) / 2

        # Get the value
        if make_value is None:
            value = bin.count
        else:
            value = make_value(bin.count)

        # Add the point to the graph
        graph.points.append(Point(coordinate, value))

    return graph

