def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        xrd = lxml.fromstring(document)
        # Parse XRD
        host = xrd.find(".//Subject").text
        webfinger_aliases = [
            node.text
            for node in xrd.find(".//Alias")
            if node.attrib.get("rel").lower() == "diaspora/federation"
        ]
        return {
            "host": host,
            "webfinger_aliases": webfinger_aliases,
        }
    except (lxml.etree.XMLSyntaxError, AttributeError):
        # Parse JSON
        data = json.loads(document)
        return {
            "host": data.get("subject").lower(),
            "webfinger_aliases": data.get("aliases", []),
        }

def parse_diaspora_webfinger(document):
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    :param document: the webfinger document as string
    :return: dict
    """
    try:
        return json.loads(document)
    except (json.JSONDecodeError, ValueError):
        root = etree.fromstring(document)
        links = [
            {"href": link.attrib["href"], "rel": link.attrib["rel"]}
            for link in root.findall(".//{*}Link")
        ]
        return {"links": links}

