def list_of_file_names(settings_dirs, spec_option):
    """Create a list of fully qualified Python filenames in the given directories

    :param settings_dirs: list of directories to search for settings files
    :param spec_option: boolean indicating whether to return a list of filenames or a list of IniType complex objects
    :return: list of fully qualified Python filenames
    """

    # Validate input parameters
    if not settings_dirs:
        raise ValueError("settings_dirs cannot be empty")
    if spec_option not in (False, True):
        raise ValueError("spec_option must be either False or True")

    # Search for settings files in the given directories
    files = []
    for settings_dir in settings_dirs:
        for root, dirs, files_ in os.walk(settings_dir):
            for file in files_:
                if file.endswith(".py"):
                    files.append(os.path.join(root, file))

    # Filter out files that do not exist or are not Python files
    files = [file for file in files if os.path.isfile(file)]

    # Return list of fully qualified Python filenames
    return files

