def validate_from_file(yaml_file=None):
    """
    Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    with open(yaml_file, 'r') as f:
        data = yaml.load(f)

    if not data:
        raise IRValidatorException("No data found in the YAML file")

    try:
        version = data['version']
        if not version:
            raise IRValidatorException("'version' field is missing")
    except KeyError as e:
        raise IRValidatorException(f"{e} field is missing")

    try:
        entrypoint = data['entrypoint']
        if not entrypoint:
            raise IRValidatorException("'entrypoint' field is missing")
    except KeyError as e:
        raise IRValidatorException(f"{e} field is missing")

    try:
        modules = data['modules']
        if not modules:
            raise IRValidatorException("'modules' field is missing")
    except KeyError as e:
        raise IRValidatorException(f"{e} field is missing")

    try:
        operators_reference = data['operators_reference']
        if not operators_reference:
            raise IRValidatorException("'operators_reference' field is missing")
    except KeyError as e:
        raise IRValidatorException(f"{e} field is missing")

    try:
        nodes = data['nodes']
        if not nodes:
            raise IRValidatorException("'nodes' field is missing")
    except KeyError as e:
        raise IRValidatorException(f"{e} field is missing")

    return data

