def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if parser_name == "main":
        parser = self.main_parser
    elif parser_name == "virsh":
        parser = self.virsh_parser
    elif parser_name == "ospd":
        parser = self.ospd_parser
    else:
        raise Exception(f"Unknown parser name: {parser_name}")

    for arg in values_dict:
        try:
            values_dict[arg] = parser.get_default(arg)
            if not isinstance(values_dict[arg], str):
                values_dict[arg] = parser.get_default(arg)
            else:
                values_dict[arg] = parser.convert_arg(arg, values_dict[arg])
        except Exception as e:
            print(f"Error converting non-CLI argument: {arg}, error: {e}")

def _convert_non_cli_args(parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if parser_name == "main":
        for key, value in values_dict.items():
            if key == "path":
                values_dict[key] = str(value)
            elif key == "verbose":
                values_dict[key] = bool(value)
    elif parser_name == "virsh":
        for key, value in values_dict.items():
            if key == "mac":
                values_dict[key] = str(value)
            elif key == "delete":
                values_dict[key] = str(value)
            elif key == "nicname":
                values_dict[key] = str(value)
    elif parser_name == "ospd":
        for key, value in values_dict.items():
            if key == "port":
                values_dict[key] = int(value)
            elif key == "host":
                values_dict[key] = str(value)
    else:
        raise ValueError(f"Invalid parser name: {parser_name}")

